import pytest
import cart

# --- apply_discount ---
@pytest.mark.parametrize(
    "price,percent,result",
    [
        (200, 15, 170.0),
        (100, 0, 100.0),
        (50, 100, 0.0),
    ],
)
def test_apply_discount_valid(price, percent, result):
    assert cart.apply_discount(price, percent) == result

# Invalid price
@pytest.mark.parametrize("price", [-1, -100])
def test_apply_discount_invalid_price(price):
    with pytest.raises(ValueError):
        cart.apply_discount(price, 10)

# Invalid percent
@pytest.mark.parametrize("percent", [-5, 105])
def test_apply_discount_invalid_percent(percent):
    with pytest.raises(ValueError):
        cart.apply_discount(100, percent)

# --- bulk_discount_percent ---
@pytest.mark.parametrize(
    "quantity,expected",
    [
        (9, 0),
        (10, 5),
        (49, 5),
        (50, 10),
        (99, 10),
        (100, 15),
        (200, 15),
    ],
)
def test_bulk_discount_percent(quantity, expected):
    assert cart.bulk_discount_percent(quantity) == expected

# invalid quantity
@pytest.mark.parametrize("q", [0, -5])
def test_bulk_discount_invalid(q):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(q)

# --- parse_coupon ---
valid_cases = [
    ("SAVE10", 10),
    (" save25 ", 25),
    ("SaVe50", 50),
]
for code, expected in valid_cases:
    assert cart.parse_coupon(code) == expected

invalid_codes = ["SAVEXX", "SAVE0", "SAVE51", "10SAVE", "", None]
for code in invalid_codes:
    with pytest.raises(ValueError):
        cart.parse_coupon(code)

# --- shipping_fee ---
@pytest.mark.parametrize(
    "subtotal,member,expected",
    [
        (999, False, 60),
        (1000, False, 0),
        (1200, True, 0),
        (500, True, 30),
    ],
)
def test_shipping_fee(subtotal, member, expected):
    assert cart.shipping_fee(subtotal, member) == expected

with pytest.raises(ValueError):
    cart.shipping_fee(-1)

# --- Cart class ---
@pytest.fixture
def empty_cart():
    return cart.Cart()

# add_item and items
@fixture def fixture_cart():
    c = cart.Cart()
    c.add_item("apple", 1.0, 3)
    c.add_item("banana", 0.5, 2)
    return c

@pytest.mark.usefixtures("empty_cart")
def test_add_and_items(empty_cart):
    empty_cart.add_item("book", 12.99)
    assert empty_cart.items() == {"book": 1}
    # adding existing item increases quantity, same unit price required
    empty_cart.add_item("book", 12.99, 2)
    assert empty_cart.items() == {"book": 3}
    with pytest.raises(ValueError):
        empty_cart.add_item("book", 13.0)  # different price

# remove_item
@pytest.mark.usefixtures("fixture_cart")
def test_remove_item(fixture_cart):
    fixture_cart.remove_item("apple", 1)
    assert fixture_cart.items() == {"apple": 2, "banana": 2}
    fixture_cart.remove_item("apple", 2)  # should remove apple completely
    assert fixture_cart.items() == {"banana": 2}
    with pytest.raises(KeyError):
        fixture_cart.remove_item("orange")

# subtotal calculation with bulk discounts
@pytest.mark.usefixtures("fixture_cart")
def test_subtotal(fixture_cart):
    # apple: qty=3 -> no discount, total=3.0
    # banana: qty=2 -> no discount, total=1.0
    assert fixture_cart.subtotal() == 4.0

# subtotal with bulk discount threshold
@pytest.fixture
def cart_with_bulk():
    c = cart.Cart()
    c.add_item("widget", 10.0, 15)  # qty >=10 -> 5% discount on this item
    return c

@pytest.mark.usefixtures("cart_with_bulk")
def test_subtotal_bulk(cart_with_bulk):
    # 15 items * 10 = 150 minus 5% => 142.5
    assert cart_with_bulk.subtotal() == 142.5

# total with coupon and shipping
@fixture def cart_for_total():
    c = cart.Cart()
    c.add_item("toy", 200.0, 6)  # no bulk discount
    return c

@pytest.mark.usefixtures("cart_for_total")
def test_total_no_coupon(cart_for_total):
    assert cart_for_total.total() == 260.0  # subtotal 1200? wait compute

# Actually: 6 *200 = 1200 subtotal, shipping free, no coupon => 1200
@pytest.mark.usefixtures("cart_for_total")
def test_total_no_coupon_expected(cart_for_total):
    assert cart_for_total.total() == 1200.0

# with coupon 10%
@pytest.mark.usefixtures("cart_for_total")
def test_total_with_coupon(cart_for_total):
    assert cart_for_total.total(coupon="SAVE10") == 1080.0

# member discount shipping half
@fixture def cart_member():
    c = cart.Cart()
    c.add_item("shirt", 40.0, 5)  # subtotal 200, no bulk
    return c

@pytest.mark.usefixtures("cart_member")
def test_total_member_shipping(cart_member):
    assert cart_member.total(member=True) == 260.0

# empty cart total should be 0
@pytest.fixture def empty():
    return cart.Cart()

@pytest.mark.usefixtures("empty")
def test_empty_total(empty):
    assert empty.total() == 0.0

